/* Header shell ----------------------------------------------------------- */
.ocean-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  box-sizing: border-box;
  min-height: 56px;
  padding: 0 16px;
  background: var(--bg-raised);
  box-shadow:
    inset 0 1px 0 var(--specular-soft),   /* top-edge light */
    0 1px 0 var(--border),                /* crisp bottom seam */
    var(--shadow-sm);                     /* soft drop over the transcript */
}

/* Desktop (Tauri overlay titlebar): the header IS the titlebar — native
   traffic lights float over its left edge, so pad the brand clear of them.
   `.is-titlebar` is set on the app root only inside the Tauri shell. */
.is-titlebar .ocean-header {
  padding-left: var(--titlebar-inset);
}

/* Native chrome spans the actual window even when the readable product shell
   is capped at --shell-max. Without this, wide collapsed-workspace windows
   strand the overflow and workspace controls at the shell edge and leave a
   dead titlebar strip before the rounded window edge. The open workspace path
   already widens the root and intentionally ends the header at the pane. */
.ocean-surface.is-titlebar:not(.has-workspace-open) .ocean-header {
  width: 100vw;
  margin-left: calc((100% - 100vw) / 2);
  flex: 0 0 auto;
}

.ocean-header__right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

/* Brand ------------------------------------------------------------------ */
.ocean-brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ocean-brand__word span:nth-child(1) { color: var(--ocean-4); }
.ocean-brand__word span:nth-child(2) { color: var(--ocean-5); }
.ocean-brand__word span:nth-child(3) { color: var(--ocean-6); }
.ocean-brand__word span:nth-child(4) { color: var(--ocean-7); }
.ocean-brand__word span:nth-child(5) { color: var(--ocean-8); }

/* Slow solid-color shimmer across the header wordmark letters. Each span
   keeps its ramp color (--letter-fill) and eases toward --letter-shimmer;
   never gradient-clip text. */
.ocean-brand__word span:nth-child(1) { --letter-fill: var(--ocean-4); }
.ocean-brand__word span:nth-child(2) { --letter-fill: var(--ocean-5); }
.ocean-brand__word span:nth-child(3) { --letter-fill: var(--ocean-6); }
.ocean-brand__word span:nth-child(4) { --letter-fill: var(--ocean-7); }
.ocean-brand__word span:nth-child(5) { --letter-fill: var(--ocean-8); }
@media (prefers-reduced-motion: no-preference) {
  .ocean-brand__word span {
    animation: ocean-brand-shimmer 5.5s ease-in-out infinite;
  }
  .ocean-brand__word span:nth-child(1) { animation-delay: 0s; }
  .ocean-brand__word span:nth-child(2) { animation-delay: -0.55s; }
  .ocean-brand__word span:nth-child(3) { animation-delay: -1.1s; }
  .ocean-brand__word span:nth-child(4) { animation-delay: -1.65s; }
  .ocean-brand__word span:nth-child(5) { animation-delay: -2.2s; }
  @keyframes ocean-brand-shimmer {
    0%, 100% { color: var(--letter-fill); }
    40% { color: color-mix(in srgb, var(--letter-fill) 35%, var(--letter-shimmer)); }
  }
}

/* Header lockup — the mark and the wordmark side by side, vertically
   centered with a quiet gap. */
.ocean-brand .wave-badge {
  flex: none;
  font-size: 24px;
}

.ocean-brand__word {
  display: inline-flex;
  /* Brand font — the same --wm-font (Poppins) the landing reveal letters
     use; the old --mono terminal face predates the wordmark switch. */
  font-family: var(--wm-font);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.22em;
  line-height: 1;
  white-space: nowrap;
  cursor: default;
}

/* Inline SVG icons inherit text color + size (1em). The default treatment is
   FILLED (the game-icons set: SoundOn/SoundOff/Amplitude) — they need
   `fill: currentColor` to be visible at all. */
.icon {
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: middle;
  fill: currentColor;
}

/* Stroke (line) icons — Menu, Council, Groups, Capture, Mic. Their SVGs
   carry `fill="none" stroke="currentColor"` as presentation attributes, but a
   class selector (`.icon`, specificity 0-1-0) outranks a presentation attribute
   (0-0-0), so the global `.icon { fill: currentColor }` above would otherwise
   FILL them — collapsing each line drawing into a solid blob. This rule uses a
   two-class selector (`.icon.icon--stroke`, specificity 0-2-0) so it
   deterministically beats `.icon` regardless of source order, restoring the
   intended outline rendering. `fill: none` cascades to the child paths/lines
   (which set no fill of their own); `stroke` + `stroke-width` are restated so
   the look never depends on the SVG attributes surviving. (OCEAN-202) */
.icon.icon--stroke {
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Header metadata chips -------------------------------------------------- */
.ocean-runtime {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding-left: 12px;
  box-shadow: inset 1px 0 0 var(--border-subtle);
}

/* Tokens are post-hoc session metadata — the least important cue, so they
   shrink and truncate first when the row tightens; the live browser + status
   cues never give up space. */
.ocean-runtime .ocean-tokens {
  min-width: 0;
  flex: 0 1 auto;
}
.ocean-runtime .ocean-tokens__io {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ocean-runtime .ocean-browser-control,
.ocean-runtime .ocean-status {
  flex: 0 0 auto;
}

.ocean-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--fg-3);
  font-family: var(--font);
  font-size: 12px;
  font-weight: 400;
  line-height: 1.35;
}

.ocean-status__dot {
  display: none;
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: var(--radius-pill);
  background: var(--ok);
}

.ocean-status.is-quiet .ocean-status__dot {
  display: block;
}


