.icon.icon--stroke {
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Header metadata chips -------------------------------------------------- */
.ocean-runtime {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding-left: 12px;
  box-shadow: inset 1px 0 0 var(--border-subtle);
}

/* Tokens are post-hoc session metadata — the least important cue, so they
   shrink and truncate first when the row tightens; the live browser + status
   cues never give up space. */
