  min-width: 0;
  flex: 0 1 auto;
}
.ocean-runtime .ocean-tokens__io {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ocean-runtime .ocean-browser-control,
.ocean-runtime .ocean-status {
  flex: 0 0 auto;
}

.ocean-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--fg-3);
  font-family: var(--font);
  font-size: 12px;
