/* ═══════════════════════════════════════════════════════════════════
   Shared slide-over overlay pattern
   ═══════════════════════════════════════════════════════════════════ */

.sessions-overlay,
.rooms-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  justify-content: flex-end;
  background: rgba(6, 6, 6, 0.72);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 280ms var(--ease);
}

.sessions-overlay--open,
.rooms-overlay--open {
  opacity: 1;
  pointer-events: auto;
}

.sessions-panel,
.rooms-panel {
  width: min(380px, 92vw);
  height: 100dvh;
  display: flex;
  flex-direction: column;
  color: var(--fg);
  background: var(--bg-raised);
  box-shadow: var(--shadow-lg);
  animation: sessions-slide-in 280ms var(--ease) both;
}

/* Sessions renders as a centered modal; rooms stays a right slide-over. */
.sessions-overlay {
  align-items: center;
  justify-content: center;
}

.sessions-panel {
  width: min(760px, calc(100vw - 28px));
  max-height: min(80vh, 720px);
  height: auto;
  background: var(--bg-elevated);
  box-shadow: var(--elev-3);
  border-radius: var(--radius-lg);
  overflow: hidden;
  animation: sessions-tidal-rise var(--dur-slow) var(--ease-tide) both;
}

/* Hidden overlay: removed from accessibility tree and layout when closed,
   overriding .sessions-overlay { display: flex }. */
.sessions-overlay[hidden] {
  display: none !important;
}

@keyframes sessions-tidal-rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes sessions-slide-in {
  from {
    transform: translateX(24px);
    opacity: 0.96;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sessions-overlay,
  .rooms-overlay {
    transition: none;
  }

  .sessions-panel,
  .rooms-panel {
    animation: none;
  }
}

