  1	//! Inline SVG icons (game-icons.net, CC-BY 3.0). Each renders at 1em and
  2	//! inherits `currentColor`, so CSS color controls them — they match the
  3	//! site palette (cyan --accent, etc.) wherever they're placed.
  4	
  5	use std::cell::RefCell;
  6	use std::rc::Rc;
  7	
  8	use leptos::prelude::*;
  9	use wasm_bindgen::closure::Closure;
 10	use wasm_bindgen::JsCast;
 11	use wasm_bindgen::JsValue;
 12	use web_sys::CanvasRenderingContext2d;
 13	
 14	// ── Tide Coin (Canvas 2D) ──────────────────────────────────────────────
 15	// Ported 1:1 from deliverables/engines/orbstudio.js kind='tide'.
 16	// The coin is drawn in the canvas backing-store coordinate space S
 17	// (S = CSS px × min(devicePixelRatio, 2)). Geometry is fractional-S,
 18	// matching the 48px design space scaled to the actual canvas size.
 19	// spinning=true churns the waterline via rAF (calm=0); false or
 20	// reduced-motion renders the static calm=1 rest state.
 21	
 22	const TAU: f64 = std::f64::consts::TAU;
 23	
 24	fn coin_base(ctx: &CanvasRenderingContext2d, s: f64) {
 25	    ctx.clear_rect(0.0, 0.0, s, s);
 26	    let g = ctx.create_linear_gradient(0.0, 0.0, 0.0, s);
 27	    let _ = g.add_color_stop(0.0, "#0F0F10");
 28	    let _ = g.add_color_stop(0.55, "#020203");
 29	    ctx.set_fill_style_canvas_gradient(&g);
 30	    ctx.begin_path();
 31	    let _ = ctx.arc(s / 2.0, s / 2.0, s * (21.0 / 48.0), 0.0, TAU);
 32	    ctx.fill();
 33	}
 34	
 35	fn clip_coin(ctx: &CanvasRenderingContext2d, s: f64) {
 36	    ctx.begin_path();
 37	    let _ = ctx.arc(s / 2.0, s / 2.0, s * (20.4 / 48.0), 0.0, TAU);
 38	    ctx.clip();
 39	}
 40	
 41	fn coin_top(ctx: &CanvasRenderingContext2d, s: f64) {
 42	    let c = s / 2.0;
 43	    // vignette
 44	    let vig = ctx
 45	        .create_radial_gradient(c, c, 0.0, c, c, s * (20.6 / 48.0))
 46	        .unwrap();
 47	    let _ = vig.add_color_stop(0.62, "rgba(0,0,0,0)");
 48	    let _ = vig.add_color_stop(1.0, "rgba(0,0,0,0.55)");
 49	    ctx.set_fill_style_canvas_gradient(&vig);
 50	    ctx.begin_path();
 51	    let _ = ctx.arc(c, c, s * (20.6 / 48.0), 0.0, TAU);
 52	    ctx.fill();
 53	    // occlusion
 54	    let occ = ctx
 55	        .create_radial_gradient(c, c, 0.0, c, c, s * (20.4 / 48.0))
 56	        .unwrap();
 57	    let _ = occ.add_color_stop(0.78, "rgba(0,0,0,0)");
 58	    let _ = occ.add_color_stop(0.94, "rgba(0,0,0,0.26)");
 59	    let _ = occ.add_color_stop(1.0, "rgba(0,0,0,0.72)");
 60	    ctx.set_fill_style_canvas_gradient(&occ);
 61	    ctx.begin_path();
 62	    let _ = ctx.arc(c, c, s * (20.4 / 48.0), 0.0, TAU);
 63	    ctx.fill();
 64	    // gloss — upper-left source, fades outward
 65	    let glo = ctx
 66	        .create_radial_gradient(c, s * 0.18, 0.0, c, s * 0.18, s * 0.6)
 67	        .unwrap();
 68	    let _ = glo.add_color_stop(0.0, "rgba(207,244,255,0.15)");
 69	    let _ = glo.add_color_stop(0.55, "rgba(207,244,255,0)");
 70	    ctx.set_fill_style_canvas_gradient(&glo);
 71	    ctx.begin_path();
 72	    let _ = ctx.arc(c, c, s * (20.4 / 48.0), 0.0, TAU);
 73	    ctx.fill();
 74	    // rim stroke
 75	    let rim = ctx.create_linear_gradient(0.0, s * (3.0 / 48.0), 0.0, s * (45.0 / 48.0));
 76	    let _ = rim.add_color_stop(0.0, "rgba(177,183,186,0.45)");
 77	    let _ = rim.add_color_stop(1.0, "rgba(107,112,115,0.45)");
 78	    ctx.set_stroke_style_canvas_gradient(&rim);
 79	    ctx.set_line_width(0.5_f64.max(s * (0.55 / 48.0)));
 80	    ctx.begin_path();
 81	    let _ = ctx.arc(c, c, s * (20.7 / 48.0), 0.0, TAU);
 82	    ctx.stroke();
 83	}
 84	
 85	/// Draw the tide water body + crest inside an already-clipped canvas.
 86	/// `amp` = 1.0 when churning, 0.25 at rest.
 87	fn draw_tide_water(ctx: &CanvasRenderingContext2d, s: f64, t: f64, amp: f64) {
 88	    let lvl = s * 0.46 + s * 0.012 * (0.8 * t).sin() * amp;
 89	    let dev = |x: f64| -> f64 {
 90	        s * (0.030 * ((x / s) * 9.2 + 1.9 * t).sin()
 91	            + 0.016 * ((x / s) * 16.4 - 1.3 * t + 2.0).sin())
 92	            * amp
 93	    };
 94	    let step = 2.0_f64.max(s / 44.0);
 95	
 96	    // ── water body ──
 97	    ctx.begin_path();
 98	    ctx.move_to(-2.0, lvl + dev(0.0));
 99	    let mut x = 0.0;
100	    while x <= s + step {
101	        ctx.line_to(x, lvl + dev(x));
102	        x += step;
103	    }
104	    ctx.line_to(s + 2.0, s + 2.0);
105	    ctx.line_to(-2.0, s + 2.0);
106	    ctx.close_path();
107	    let wg = ctx.create_linear_gradient(0.0, lvl - s * 0.05, 0.0, s);
108	    let _ = wg.add_color_stop(0.0, "rgba(46,166,198,0.52)");
109	    let _ = wg.add_color_stop(0.5, "rgba(28,99,176,0.60)");
110	    let _ = wg.add_color_stop(1.0, "rgba(10,22,66,0.78)");
111	    ctx.set_fill_style_canvas_gradient(&wg);
112	    ctx.fill();
113	
114	    // ── subsurface strata echoes ──
115	    ctx.set_stroke_style_str("rgba(5,16,31,0.5)");
116	    ctx.set_line_width(0.6_f64.max(s * 0.008));
117	    for b in 1..=3 {
118	        let by = lvl + (s - lvl) * (b as f64 / 4.0);
119	        ctx.begin_path();
120	        let mut x = 0.0;
121	        while x <= s + step {
122	            let y = by + dev(x + (b * 17) as f64) * (0.5 / b as f64);
123	            if x == 0.0 {
124	                ctx.move_to(-2.0, y);
125	            } else {
126	                ctx.line_to(x, y);
127	            }
128	            x += step;
129	        }
130	        ctx.stroke();
131	    }
132	
133	    // ── crest (double-stroke waterline for foam) ──
134	    // Draw the waterline path into the current path, then stroke it twice
135	    // with different width/opacity for the foam effect.
136	    let crest_path = |ctx: &CanvasRenderingContext2d| {
137	        ctx.begin_path();
138	        let mut x = 0.0;
139	        while x <= s + step {
140	            let y = lvl + dev(x);
141	            if x == 0.0 {
142	                ctx.move_to(-2.0, y);
143	            } else {
144	                ctx.line_to(x, y);
145	            }
146	            x += step;
147	        }
148	    };
149	    ctx.set_stroke_style_str("rgba(191,239,248,0.30)");
150	    ctx.set_line_width(1.4_f64.max(s * 0.030));
151	    crest_path(ctx);
152	    ctx.stroke();
153	    ctx.set_stroke_style_str("rgba(234,252,255,0.85)");
154	    ctx.set_line_width(0.7_f64.max(s * 0.012));
155	    crest_path(ctx);
156	    ctx.stroke();
157	}
