159	/// Full tide frame: coin base → water → coin top.
160	fn draw_tide_frame(ctx: &CanvasRenderingContext2d, s: f64, t: f64, spinning: bool) {
161	    coin_base(ctx, s);
162	    ctx.save();
163	    clip_coin(ctx, s);
164	    let amp = if spinning { 1.0 } else { 0.25 };
165	    draw_tide_water(ctx, s, t, amp);
166	    ctx.restore();
167	    coin_top(ctx, s);
168	}
